export interface ArchetypeEntry {
  name: string;
  line: string; // completes "the one who..."
}

export type ArchetypeLookup = Record<string, ArchetypeEntry>;

export interface FunctionMeta {
  key: FunctionKey;
  title: string;
  tagline: string;
  pair: [PlanetKey, PlanetKey];
  glyphs: [string, string];
  definition: string;
  archetypes: ArchetypeLookup;
}

// Helper: build the sign-pair key (ordered — mirrors are distinct archetypes)
export function signPairKey(signA: number, signB: number): string {
  return `${signA}_${signB}`;
}

